package ru.ultimavox.itsm.servicedesk.application;
import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.jdbc.core.JdbcTemplate; import ru.ultimavox.itsm.platform.audit.AuditTrail; import ru.ultimavox.itsm.platform.event.DomainEvent; import ru.ultimavox.itsm.platform.outbox.IntegrationEventOutbox;
@ExtendWith(MockitoExtension.class) class CreateWorkItemTest {
 @Mock JdbcTemplate jdbc; @Mock AuditTrail audit; @Mock IntegrationEventOutbox outbox; @Captor ArgumentCaptor<AuditTrail.Entry> auditEntry; @Captor ArgumentCaptor<DomainEvent> event;
 @Test void atomically_describes_audited_incident_and_outbox_event(){ when(jdbc.queryForObject("SELECT nextval('work_item_number_seq')",Long.class)).thenReturn(1000L); var result=new CreateWorkItem(jdbc,audit,outbox).create(new CreateWorkItem.Command(CreateWorkItem.Type.INCIDENT,"VPN unavailable","Remote employees cannot connect","Workplace"),"user-42"); assertThat(result.number()).isEqualTo("INC-001000"); assertThat(result.state()).isEqualTo("NEW"); verify(audit).append(auditEntry.capture()); verify(outbox).record(event.capture()); assertThat(auditEntry.getValue().actorId()).isEqualTo("user-42"); assertThat(auditEntry.getValue().action()).isEqualTo("work-item.created"); assertThat(event.getValue().type()).isEqualTo("incident.created"); assertThat(event.getValue().correlationId()).isEqualTo(auditEntry.getValue().correlationId()); }
}
